//! 🧪️ The actual empty presence/transient source keeps its physical registries and native issuers through every cancellation prefix.
use super::*;
fn law()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).unwrap()}
fn grant()->RetainedCloneGrant{let law=law();let g=&law["turn"];RetainedCloneGrant{maximum_items:g["items"].as_u64().unwrap()as usize,maximum_copy_bytes:g["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["depth"].as_u64().unwrap()as usize}}
fn new_caller(operation:u64)->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(operation),Generation(47),RetainedCloneGrant{maximum_items:1<<28,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096},default_now_us,u64::MAX,1<<28)}
fn turn_with<T>(grant:RetainedCloneGrant,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(grant,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"empty native ephemeral physical receipt={p:?} failure={:?}",result.as_ref().err());result.unwrap()}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{turn_with(grant(),caller,decoder,run)}
#[test]
fn original_ephemeral_source_same_roots_cancelled_prefixes_and_full_physical_close(){let law=law();for cutoff in std::iter::once(usize::MAX).chain(law["cancelAfter"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as usize)){let mut caller=new_caller(5101);let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;assert!(!turn(&mut caller,&mut decoder,|cx|OriginalEmptyEphemeralSource::admit(cx,&mut source)));assert!(source.is_none());assert!(turn_with(semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT.preparation,&mut caller,&mut decoder,|cx|OriginalEmptyEphemeralSource::admit(cx,&mut source)));let mut ready=false;for index in 0..cutoff.min(65536){ready=turn(&mut caller,&mut decoder,|cx|source.as_mut().unwrap().advance(cx));if ready{break}assert!(index<65535,"ephemeral registry source phase {}",source.as_ref().unwrap().progress())}let mut foreign=new_caller(5102);let mut foreign_decoder=OriginalJobDecodeOwner::empty();let foreign_grant=grant();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn_with_decoder(foreign_grant,&mut foreign_decoder,|cx|source.as_mut().unwrap().advance(cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));foreign.retire(grant());let mut output=None;if cutoff==usize::MAX{assert!(ready);assert_eq!(source.as_ref().unwrap().progress(),law["readyPhase"].as_u64().unwrap()as u8);let pointer=std::ptr::from_ref(source.as_ref().unwrap().owned.as_ref().unwrap().presence().local());assert!(turn(&mut caller,&mut decoder,|cx|source.as_mut().unwrap().take(cx,&mut output)));assert_eq!(std::ptr::from_ref(output.as_ref().unwrap().presence().local()),pointer);assert!(source.as_ref().unwrap().terminal_is_empty());assert_eq!(*output.as_ref().unwrap().presence().local(),NoPresence{});let _=output.as_ref().unwrap().transient();}caller.cancel().cancel_now();for index in 0..65536{if source.as_ref().unwrap().terminal_is_empty(){break}turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|source.as_mut().unwrap().close_step(cx)));assert!(index<65535,"ephemeral close remained at phase {}",source.as_ref().unwrap().progress());}let d=OriginalEmptyEphemeralSource::boxed_release_demands();turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|_|{source=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));if let Some(owned)=output.as_mut(){for index in 0..65536{if owned.terminal_is_empty(){break}turn(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|owned.close_step(cx)));assert!(index<65535,"[DEBUG] original ready ephemeral payload did not close: presence={:?} transient={:?} factories={:?} cursors={:?} total={:?}",owned.presence.as_ref().map(|value|owned.presence_disposer.as_ref().map(|closer|(closer.terminal_is_empty(value),closer.retirement_demands(value,4096)))),owned.transient.as_ref().map(|value|owned.transient_disposer.as_ref().map(|closer|(closer.terminal_is_empty(value),closer.retirement_demands(value,4096)))),(owned.presence_factory.as_ref().map(Arc::strong_count),owned.transient_factory.as_ref().map(Arc::strong_count)),owned.factory_close.iter().map(|close|close.as_ref().map(|close|(close.terminal_is_empty(),close.demands(4096)))).collect::<Vec<_>>(),caller.cumulative_receipt());}}while !decoder.terminal_is_empty(){caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(grant());}}

#[test]
fn original_ephemeral_birth_denies_each_currency_before_any_owner_exists(){for axis in 0..4{let mut caller=new_caller(5103);let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;let mut denied=semio_framework_plugin_mounted_owner::MountedOwnerPolicyV1::INTERACTIVE_COMPONENT.preparation;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,_=>denied.maximum_depth=0}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(denied,&mut decoder,|cx|OriginalEmptyEphemeralSource::admit(cx,&mut source)));assert!(!result.unwrap());assert!(source.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(caller.receipt(),RetainedCloneProgress::default());caller.retire(grant());}}
